questionvariables.text:
/* A is m x n, x is p x 1. Defined iff n = p. */
m : rand(2)+2;                         /* rows of A: 2 or 3 */
n : rand(2)+2;                         /* cols of A: 2 or 3 */
defcase : rand([true,true,false]);     /* ~2/3 of variants are defined */
p : if defcase then n else 5-n;        /* p = n (defined) or the other of 2/3 */

MM  : genmatrix(lambda([i,j], rand(11)-5), m, n);   /* entries -5..5 */
vv0 : genmatrix(lambda([i,j], rand(11)-5), p, 1);
/* guard: if a defined product would be the zero vector, nudge x so the
   'defined' answer is visibly non-zero (lazy if: A.vv0 only formed when defined) */
vv : if defcase then (if zeromatrixp(MM . vv0) then vv0 + 1 else vv0) else vv0;

ta   : if defcase then MM . vv else zeromatrix(m,1);   /* model answer */
ddef : if defcase then 1 else 0;                        /* numeric flag for PRT/feedback */

/* diagnostic helpers (used by the question tests on a defined variant) */
onescol   : genmatrix(lambda([i,j], 1), m, 1);
wrongprod : ta + onescol;              /* non-zero, != ta: an arithmetic slip */
